import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LeadMagnetCampaignRow, LeadMagnetPlatform } from "./types.ts";
import { commentMatchesKeyword } from "./types.ts";

export type MatchedCampaign = LeadMagnetCampaignRow & {
  posts: Array<{ media_id: string }>;
};

export async function findMatchingLeadMagnetCampaign(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    platform: LeadMagnetPlatform;
    accountId: string;
    mediaId: string;
    commentText: string;
  },
): Promise<MatchedCampaign | null> {
  const { data: campaigns, error } = await admin
    .from("lead_magnet_campaigns")
    .select("*")
    .eq("organization_id", args.organizationId)
    .eq("platform", args.platform)
    .eq("account_id", args.accountId)
    .eq("status", "active");

  if (error || !campaigns?.length) return null;

  for (const campaign of campaigns as LeadMagnetCampaignRow[]) {
    if (!commentMatchesKeyword(args.commentText, campaign.keyword)) continue;

    const { data: posts } = await admin
      .from("lead_magnet_campaign_posts")
      .select("media_id")
      .eq("campaign_id", campaign.id)
      .eq("media_id", args.mediaId);

    if (!posts?.length) continue;

    return { ...campaign, posts };
  }

  return null;
}

export async function enrollmentExists(
  admin: SupabaseClient,
  campaignId: string,
  participantScopedId: string,
): Promise<boolean> {
  const { data } = await admin
    .from("lead_magnet_enrollments")
    .select("id")
    .eq("campaign_id", campaignId)
    .eq("participant_scoped_id", participantScopedId)
    .maybeSingle();
  return Boolean(data?.id);
}
